      ]
    }],
    "TaskCompleted": [{
      "hooks": [{"type": "command", "command": "python3 -B \"${CLAUDE_PLUGIN_ROOT}/hooks/reconcile-task-lifecycle.py\" --event task-completed --repo-root \"${CLAUDE_PROJECT_DIR}\"", "timeout": 20}]
